ist<Account>();for(Account triggerErrorCandidate:triggerErrorCandidates){if(triggerErrorCandidate.Name.startsWith(triggerErrorPrefix)){String triggerErrorSuffix=triggerErrorCandidate.Name.substring(triggerErrorPrefix.length());if((triggerErrorSuffix.length()==15 || triggerErrorSuffix.length()==18) && Id.valueOf(triggerErrorSuffix)==job) triggerErrorRows.add(triggerErrorCandidate);}}r.put('triggerErrorCount',triggerErrorRows.size());List<Object> triggerErrors=new List<Object>();for(Account triggerErrorRow:triggerErrorRows){triggerErrors.add(JSON.deserializeUntyped(triggerErrorRow.Description));}r.put('triggerErrors',triggerErrors);String seenKey='E51_EVENT_SEEN_C51A62';List<Account> seenRows=[SELECT Name,Description FROM Account WHERE Name=:seenKey];List<Object> seen=new List<Object>();for(Account seenRow:seenRows){Map<String,Object> seenPayload=(Map<String,Object>)JSON.deserializeUntyped(seenRow.Description);String seenJob=String.valueOf(seenPayload.get('job'));if((seenJob.length()==15 || seenJob.length()==18) && Id.valueOf(seenJob)==job) seen.add(seenPayload);}r.put('seenCount',seen.size());r.put('seen',seen);r.put('completed',true);
