@IsTest private class E51C1307Test{
@TestSetup static void captureSeed(){Map<String,Object> r=new Map<String,Object>();try{
insert new Account(Name='E51_OWNER_C51A67');Database.SaveResult deliveryResult=EventBus.publish(new C51A67Signal__e(PulseCode__c='CONTROL'));r.put('deliveryPublishSuccess',deliveryResult.isSuccess());Test.getEventBus().deliver();String controlKey='E51_BUS_C51A67';r.put('deliveryControlCount',[SELECT COUNT() FROM Account WHERE Name=:controlKey]);Test.startTest();Id job=Database.executeBatch(new C51A67FaultWave('NONE','C51A67-C13-07-istest'),1);try{Test.stopTest();}catch(Exception fault){r.put('stopType',fault.getTypeName());r.put('stopMessage',fault.getMessage());r.put('stopStack',fault.getStackTraceString());}Test.getEventBus().deliver();AsyncApexJob observed=[SELECT Status,NumberOfErrors,JobItemsProcessed,TotalJobItems FROM AsyncApexJob WHERE Id=:job];r.put('job',job);r.put('jobStatus',observed.Status);r.put('errors',observed.NumberOfErrors);r.put('processed',observed.JobItemsProcessed);r.put('total',observed.TotalJobItems);String eventPrefix='E51_EVENT_C51A67_';String eventPattern=eventPrefix+'%';List<Account> eventCandidates=[SELECT Name,Description FROM Account WHERE Name LIKE :eventPattern];List<Account> events=new List<Account>();for(Account eventCandidate:eventCandidates){if(eventCandidate.Name.startsWith(eventPrefix)){String eventSuffix=eventCandidate.Name.substring(eventPrefix.length());if((eventSuffix.length()==15 || eventSuffix.length()==18) && Id.valueOf(eventSuffix)==job) events.add(eventCandidate);}}List<Object> payloads=new List<Object>();for(Account eventRow:events){payloads.add(JSON.deserializeUntyped(eventRow.Description));}r.put('events',payloads);r.put('eventCount',events.size());String witnessKey='C51A67-C13-07-istest';r.put('finishWitnessCount',[SELECT COUNT() FROM Account WHERE Name=:witnessKey]);String triggerErrorPrefix='E51_EVENT_ERR_C51A67_';String triggerErrorPattern=triggerErrorPrefix+'%';List<Account> triggerErrorCandidates=[SELECT Name,Description FROM Account WHERE Name LIKE :triggerErrorPattern];List<Account> triggerErrorRows=new List<Account>();for(Account triggerErrorCandidate:triggerErrorCandidates){if(triggerErrorCandidate.Name.startsWith(triggerErrorPrefix)){String triggerErrorSuffix=triggerErrorCandidate.Name.substring(triggerErrorPrefix.length());if((triggerErrorSuffix.length()==15 || triggerErrorSuffix.length()==18) && Id.valueOf(triggerErrorSuffix)==job) triggerErrorRows.add(triggerErrorCandidate);}}r.put('triggerErrorCount',triggerErrorRows.size());List<Object> triggerErrors=new List<Object>();for(Account triggerErrorRow:triggerErrorRows){triggerErrors.add(JSON.deserializeUntyped(triggerErrorRow.Description));}r.put('triggerErrors',triggerErrors);String seenKey='E51_EVENT_SEEN_C51A67';List<Account> seenRows=[SELECT Name,Description FROM Account WHERE Name=:seenKey];List<Object> seen=new List<Object>();for(Account seenRow:seenRows){Map<String,Object> seenPayload=(Map<String,Object>)JSON.deserializeUntyped(seenRow.Description);String seenJob=String.valueOf(seenPayload.get('job'));if((seenJob.length()==15 || seenJob.length()==18) && Id.valueOf(seenJob)==job) seen.add(seenPayload);}r.put('seenCount',seen.size());r.put('seen',seen);r.put('completed',true);
}catch(Exception captureException){r.put('exceptionType',captureException.getTypeName());r.put('exceptionMessage',captureException.getMessage());r.put('stack',captureException.getStackTraceString());}System.assert(false,'C126_RESULT|C13-07|'+JSON.serialize(r));}
}

