rErrorPrefix='SyntheticEventErrorPrefix';String triggerErrorPattern=triggerErrorPrefix+'%';List<Account> triggerErrorCandidates=[SELECT Name,Description FROM Account WHERE Name LIKE :triggerErrorPattern];List<Account> triggerErrorRows=new List<Account>();for(Account triggerErrorCandidate:triggerErrorCandidates){if(triggerErrorCandidate.Name.startsWith(triggerErrorPrefix)){String triggerErrorSuffix=triggerErrorCandidate.Name.substring(triggerErrorPrefix.length());if((triggerErrorSuffix.length()==15 || triggerErrorSuffix.length()==18) && Id.valueOf(triggerErrorSuffix)==job) triggerErrorRows.add(triggerErrorCandidate);}}r.put('triggerErrorCount',triggerErrorRows.size());String seenKey='SyntheticEventSeenKey';List<Account> seenRows=[SELECT Name,Description FROM Account WHERE Name=:seenKey];List<Object> seen=new List<Object>();for(Account seenRow:seenRows){Map<String,Object> seenPayload=(Map<String,Object>)JSON.deserializeUntyped(seenRow.Description);String seenJob=String.valueOf(seenPayload.get('job'));if((seenJob.length()==15 || seenJob.length()==18) && Id.valueOf(seenJob)==job) seen.add(seenPayload);}r.put('seenCount',seen.size());r.put('completed',true);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());}String captureJson=JSON.serialize(r);if(captureJson.length()>552){captureJson=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'payload-too-long','length'=>captureJson.length()});}System.assert(false,'C126_RESULT|C13-07-METHOD|'+captureJson);
}
