@IsTest static void observe(){
Map<String,Object> r=new Map<String,Object>();try{insert new Account(Name='SyntheticOwnerKey');Database.SaveResult deliveryResult=EventBus.publish(new SignalPulse__e(PulseCode__c='CONTROL'));r.put('deliveryPublishSuccess',deliveryResult.isSuccess());Test.getEventBus().deliver();String controlKey='SyntheticBusKey';r.put('deliveryControlCount',[SELECT COUNT() FROM Account WHERE Name=:controlKey]);r.put('stopType',null);r.put('stopMessage',null);Test.startTest();Id job=Database.executeBatch(new FaultWave('START','SyntheticCellTag'),1);try{Test.stopTest();}catch(Exception fault){r.put('stopType',fault.getTypeName());r.put('stopMessage',fault.getMessage());}Test.getEventBus().deliver();AsyncApexJob observed=[SELECT Status,NumberOfErrors,JobItemsProcessed,TotalJobItems FROM AsyncApexJob WHERE Id=:job];r.put('jobPresent',job!=null);r.put('jobStatus',observed.Status);r.put('errors',observed.NumberOfErrors);r.put('processed',observed.JobItemsProcessed);r.put('total',observed.TotalJobItems);String eventPrefix='SyntheticEventPrefix';String eventPattern=eventPrefix+'%';List<Account> eventCandidates=[SELECT Name,Description FROM Account WHERE Name LIKE :eventPattern];List<Account> events=new List<Account>();for(Account eventCandidate:eventCandidates){if(eventCandidate.Name.startsWith(eventPrefix)){String eventSuffix=eventCandidate.Name.substring(eventPrefix.length());if((eventSuffix.length()==15 || eventSuffix.length()==18) && Id.valueOf(eventSuffix)==job) events.add(eventCandidate);}}List<Object> payloads=new List<Object>();for(Account eventRow:events){Map<String,Object> eventPayload=(Map<String,Object>)JSON.deserializeUntyped(eventRow.Description);payloads.add(new Map<String,Object>{'phase'=>eventPayload.get('phase'),'type'=>eventPayload.get('type'),'message'=>eventPayload.get('message')});}r.put('events',payloads);r.put('eventCount',events.size());String witnessKey='SyntheticCellTag';r.put('finishWitnessCount',[SELECT COUNT() FROM Account WHERE Name=:witnessKey]);String triggerErrorPrefix='SyntheticEventErrorPrefix';String triggerErrorPattern=triggerErrorPrefix+'%';List<Account> triggerErrorCandidates=[SELECT Name,Description FROM Account WHERE Name LIKE :triggerErrorPattern];List<Account> triggerErrorRows=new List<Account>();for(Account triggerErrorCandidate:triggerErrorCandidates){if(triggerErrorCandidate.Name.startsWith(triggerErrorPrefix)){String triggerErrorSuffix=triggerErrorCandidate.Name.substring(triggerErrorPrefix.length());if((triggerErrorSuffix.length()==15 || triggerErrorSuffix.length()==18) && Id.valueOf(triggerErrorSuffix)==job) triggerErrorRows.add(triggerErrorCandidate);}}r.put('triggerErrorCount',triggerErrorRows.size());String seenKey='SyntheticEventSeenKey';List<Account> seenRows=[SELECT Name,Description FROM Account WHERE Name=:seenKey];List<Object> seen=new List<Object>();for(Account seenRow:seenRows){Map<String,Object> seenPayload=(Map<String,Object>)JSON.deserializeUntyped(seenRow.Description);String seenJob=String.valueOf(seenPayload.get('job'));if((seenJob.length()==15 || seenJob.length()==18) && Id.valueOf(seenJob)==job) seen.add(seenPayload);}r.put('seenCount',seen.size());r.put('completed',true);}catch(Exception fault){r.put('exceptionType',fault.getTypeName());r.put('exceptionMessage',fault.getMessage());}String captureJson=JSON.serialize(r);if(captureJson.length()>552){captureJson=JSON.serialize(new Map<String,Object>{'captureTransportError'=>'payload-too-long','length'=>captureJson.length()});}System.assert(false,'C126_RESULT|C13-01-METHOD|'+captureJson);
}
}

